mapper.select:
SELECT * FROM memory_document
WHERE tenant_id = #{tenantId} AND id = #{id}
LIMIT 1

mapper.update:
UPDATE memory_document
SET path = #{path}, content_md = #{contentMd}, content_sha256 = #{contentSha256},
    byte_size = #{byteSize}, modified_at = CURRENT_TIMESTAMP(3), deleted_at = NULL,
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND store_id = #{storeId}
  AND version = #{version}

UPDATE memory_document
SET content_md = '', content_sha256 = '', byte_size = 0,
    deleted_at = CURRENT_TIMESTAMP(3), version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND store_id = #{storeId}
  AND version = #{version} AND deleted_at IS NULL
